// Command server runs the API with demo data.
package main

import (
	"log"
	"net/http"
	"os"
	"time"

	"example.com/saasapi/internal/api"
	"example.com/saasapi/internal/store"
)

func main() {
	st := store.New()
	st.AddAccount(store.Account{ID: "acc_acme", Name: "Acme", Plan: store.PlanFree, TaxRateBP: 825})
	st.AddAccount(store.Account{ID: "acc_globex", Name: "Globex", Plan: store.PlanPro, TaxRateBP: 2000})
	st.AddKey("demo-acme", "acc_acme")
	st.AddKey("demo-globex", "acc_globex")
	if _, err := st.CreateCustomer("acc_acme", "Jane Doe", "jane@example.com", store.PlanPro, time.Now()); err != nil {
		log.Fatal(err)
	}
	addr := ":8080"
	if p := os.Getenv("PORT"); p != "" {
		addr = ":" + p
	}
	srv := &http.Server{Addr: addr, Handler: api.New(st, api.Options{}), ReadHeaderTimeout: 10 * time.Second}
	log.Printf("listening on %s", addr)
	log.Fatal(srv.ListenAndServe())
}
----
# saasapi

The billing API of a small multi-tenant SaaS product. Standard library only.

- `internal/store`: accounts, API keys, customers and invoices, kept in memory.
- `internal/billing`: invoice totals. All amounts are integer cents.
- `internal/api`: the JSON HTTP API. Every request under `/api/` needs an `X-API-Key` header. A key belongs to one account,
  and the API only ever shows that account's data: another account's customer or invoice is "not found".
- `cmd/server`: runs the API on `:8080` (or `$PORT`) with demo data.

Other services and the dashboard depend on the exported functions of `internal/store`, `internal/billing` and `internal/api`:
keep their signatures.

Run the tests with `go test ./...`.
